import sys, os, re
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
import gen

OUT = gen.OUT
os.makedirs(OUT, exist_ok=True)
REF = os.path.join(gen.OUT2, "reference_cast_sheet.jpg")

BASE = re.sub(r"The ghost is always:.*?never silly or cute\. ", "", gen.FIX6_RULE, flags=re.S)
BASE = BASE.replace("There is exactly ONE ghost in the picture and it is faint, never solid. ", "")
EXTRA = (
    "BOOK 2 CAST NOTES: Scally (the wee scallywag, pointed ears, messy black-brown hair with a leaf) now wears only thick grey wool socks and no boots, unless the scene says otherwise; a tiny plain brown bird called Fourpence often perches on Scally's head or a roof. "
    "OLD WALT is a very old stream-keeper with a grey beard that grows in two directions, a battered hat made of eel-skin, one stiff leg stuck out, a long wooden pole with an iron hook, kind weathered face, round human ears. "
    "DUMPLING is a small round grey donkey with ears like two dry leaves and a wise sleepy face. "
    "Adults have ordinary round human ears and are drawn taller than the children. Hal's slate is a small old black chalkboard in a rough wooden frame. Any sign shows only abstract scribbles, no readable letters. "
    "No ghost, no old miller ghost anywhere. RULE: include ONLY the characters named; each doing something that matters; nobody idle; nobody looks at the viewer; never lined up in a row; vary heights and angles. Scene: ")

S = {
 "b42_dry_seat": "DYNAMIC COMPOSITION, a low or high camera angle, characters at different heights, mid-action and reacting to each other, nobody facing the viewer, no row. A rain-swept rocky shoulder with a huge lone oak. Scally (pointed ears, grey socks) lounges grandly under the oak's branches in the dry, arms spread on the roots, holding out a hand for pennies with a great fake-honest smile, a tiny brown bird on his head; in the rain in front of him Hopsi (pointed ears, hops wreath, hair dripping) looks up at the tall tree and then straight at him with a calm questioning face, one finger pointing at the sky where a pale violet flash is just lighting the clouds; Hal and Titch run in from the side shielding their heads. Exactly Scally, Hopsi, Hal, Titch.",
 "b43_walt_story": "DYNAMIC COMPOSITION, a low or high camera angle, characters at different heights, mid-action and reacting to each other, nobody facing the viewer, no row. Night at the campfire. Walt sits forward with his stiff leg out and the firelight on his old face, telling a story with his hands; in the rising smoke above the fire a faint golden dream-picture shows a small boy of ten being led by the hand across a grey bog by a tall thin man in a long coat who offers a paper bag of sweets, pointing the way. The children gather round in different poses: Hal with his chin on his fists, Titch hugging her knees, Tabitha leaning on Gucci, Hopsi staring into the smoke, Scally pale, holding his own elbows. Exactly Walt, the five children and Gucci.",
 "b44_scouting": "DYNAMIC COMPOSITION, a low or high camera angle, characters at different heights, mid-action and reacting to each other, nobody facing the viewer, no row. A wide flat meadow with a stream looping in great bends, white fog beginning to roll in. In the middle distance Scally (pointed ears, grey socks) is dashing away across a green neck of land between two bends, looking back over his shoulder with a huge cheeky grin and waving; in the foreground Walt turns round from feeding Dumpling and throws up his hands, Titch drops her crust, Hal reaches after Scally, Hopsi lifts her chin with a knowing face. Exactly Scally, Walt, Dumpling, Titch, Hal, Hopsi.",
 "b45_brown_water": "DYNAMIC COMPOSITION, a low or high camera angle, characters at different heights, mid-action and reacting to each other, nobody facing the viewer, no row. After a storm on a rocky gorge path. Hal (round ears) kneels at the edge of the stream pointing in alarm at the water, which has turned the colour of cocoa, thick and full of sticks and froth, a whole branch sweeping past; Walt beside him shades his eyes, looking up at the sky and listening, one hand cupped to his ear; golden echoes of a faint distant rumbling in the air; in the background Titch, Tabitha, Hopsi and Scally look up the valley uneasily. Exactly Hal, Walt, Titch, Tabitha, Hopsi, Scally and Gucci.",
 "b46_mother_rules": "DYNAMIC COMPOSITION, a low or high camera angle, characters at different heights, mid-action and reacting to each other, nobody facing the viewer, no row. Morning at the mill yard. Hal's mother, a warm weathered woman in a kerchief, crouches in front of Hal (round ears) holding his face in both hands, counting four things on her fingers, her eyes anxious and loving; Hal listens solemnly with his slate under his arm; behind them Walt on his small grey donkey waits at the gate with the whistle in his hand; Gucci sits against Hal's leg. A slate hangs by a string on the mill door. Exactly Hal's mother, Hal, Walt, Dumpling, Gucci.",
 "b47_walt_sack": "DYNAMIC COMPOSITION, a low or high camera angle, characters at different heights, mid-action and reacting to each other, nobody facing the viewer, no row. A foggy meadow after a rescue. Scally (pointed ears), shivering and covered in grey clay from the neck down, sits hunched on the grass; Walt, kind and gruff, wraps a sack round his shoulders and rubs his back, sharing his bread; Hopsi sits beside him calmly with her hand on his arm; Titch hands over a crust; Hal coils the muddy rope; Tabitha watches from behind. Gentle, quiet, comforting. Exactly Scally, Walt, Hopsi, Titch, Hal, Tabitha.",
 "b48_counting_notes": "DYNAMIC COMPOSITION, a low or high camera angle, characters at different heights, mid-action and reacting to each other, nobody facing the viewer, no row. Early morning on the mill step. Tabitha (curly bun) sits upright counting sounds on her fingers with a determined frown, her lips moving, one hand cupped to her ear; around her the others slump half asleep: Hal flat on his back with his slate on his face, Titch with her red cap over her eyes and a crust in each hand, Hopsi sitting rigid and green about the gills, Scally sprawled across the top step with his arm over his face; faint golden music notes drift in the air above the pond; on the roof a tiny brown bird sings its four notes. Exactly the five children and the bird.",
 "b01_hum_night": "Night in a small attic bedroom at the mill. Hal (brown hair, round ears) lies wide awake in bed staring at the ceiling, on which faint golden wavy lines of sound ripple across the boards; baby wolf Gucci lies across his feet with his ears folded inside out in misery; through the little window on the roof a tiny brown bird sings with its beak open under a thin moon. Moonlight and quiet humour. Exactly Hal, Gucci and the bird.",
 "b02_draught_sale": "ALL villagers, the baker, the mother and every adult and every village child have clearly ROUND human ears with no points at all; only Scally and Hopsi have pointed ears. DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. A sunny village road beside the mill. Scally (pointed ears, messy hair, grey socks) leans over a big bubbling cauldron ladling a murky brown brew into a tin cup with a grand flourish and the most innocent face in the world; beside it a hand-painted sign of unreadable scribbles. A tired plump baker (Mrs Crumb, floury apron) tips back the cup with her eyes shut; two sleepy villagers lean forward holding out pennies; Hopsi (pointed ears, hops wreath) has her head right over the cauldron, sniffing it with a suspicious frown. Exactly Scally, Hopsi, Mrs Crumb and two villagers.",
 "b03_pennies_back": "ALL villagers, the baker, the mother and every adult and every village child have clearly ROUND human ears with no points at all; only Scally and Hopsi have pointed ears. DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. Scally (pointed ears, ears bright red, head down, grey socks) hurries along a line of villagers dropping pennies back into their palms one by one; a young mother with a baby leans down and kisses his cheek and he squirms and screws up his face; a brown cauldron lies tipped over with brown water running down the road. Hopsi (pointed ears) sits on a barrel in the background eating a hop, watching him with a small pleased smile. Exactly Scally, Hopsi, the mother with her baby and two villagers.",
 "b04_reflection_up": "Dawn at the mill pond. Hal (round ears, tired, hair like a hedge) kneels at the water's edge looking down, and his reflection looks back and winks, its mouth forming a shape; faint golden music-note ribbons rise from the pond surface. Quiet, magical and funny. Only Hal and his reflection.",
 "b05_mayor_barrel": "The mill yard crowded with sleepy villagers. A pompous Mayor in a chain of office and a waistcoat stands on a barrel pointing dramatically at the stream and shouting orders; the miller (stocky, bearded, leaning on a stick) folds his arms and scowls up at him; in the foreground at the back of the crowd Scally whispers eagerly into Hal's ear while Hopsi stands behind them, listening, arms folded, with a patient look. Exactly the Mayor, the miller, Scally, Hal, Hopsi and a handful of villagers.",
 "b06_walt_arrives": "A grey donkey (Dumpling) plods into the mill yard through the gate carrying Old Walt, with his two-way beard, eel-skin hat and stiff leg stuck out, a long hooked pole over his shoulder; the villagers part and stare; the Mayor on his barrel stops mid-sentence with his mouth open; Tabitha (curly bun, round ears) whispers to Hal and points. Exactly Walt, Dumpling, the Mayor, Tabitha, Hal and a few villagers.",
 "b07_walt_stick": "Walt, leaning on his pole, drops a stick into the stream and the children crowd round the bank watching it bob away past the mill wheel: Hal crouched with his slate, Titch (red cap) on tiptoe with a crust, Tabitha pointing at the current, Scally flat on his stomach with his chin on the bank, Hopsi kneeling and watching the stick turn. Everyone watching the stick. Exactly Walt, Hal, Titch, Tabitha, Scally, Hopsi; no wolf.",
 "b08_setting_off": "Dawn on a path beside a stream. Walt rides the small grey donkey Dumpling at the front, one stiff leg out. Behind them the children and baby wolf Gucci: Gucci with his nose down following a smell, Titch with a bag of crusts, Hal checking the slate, Tabitha asking Walt a question with her hand on the donkey, Hopsi last with her bowl of hops, Scally kicking pebbles ahead in his socks. Mist on the water and the mill small behind. All walking, moving, talking.",
 "b09_green_pool": "A wide dark green pool of still water where a slipped bank blocks the path. Walt on foot points at the pool with his hooked pole, explaining; Scally stands on the edge looking at the water boldly with one sock lifted as if about to wade, Hal grabs the back of his jacket, Tabitha shakes her head, Titch drops her bag, Hopsi sits on a stone watching them with a hop in her fingers, Gucci sniffs the edge. Exactly the six children, Walt, Dumpling and Gucci.",
 "b10_apple_swap": "DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. Beside the green pool. Scally (pointed ears, grey socks) creeps toward the water's edge hiding a red-painted stone in his fist behind his back while he grins with great false innocence; the real apple peeks out of his other sleeve. Hopsi (pointed ears) is sitting on a stone with her back half turned to him, pointing at the stone without looking, one eyebrow raised. Tabitha (curly bun) leans forward with her hands on her hips, catching him; Hal (round ears) peers over with his slate raised; Titch (red cap) hauls a log up the bank and stops mid-step. Exactly Scally, Hopsi, Tabitha, Hal, Titch.",
 "b11_float_test": "At the edge of the green pool Hal kneels testing what floats: a floating apple, a sinking stone with rings spreading, a log floating high, and Scally's big brown boot floating upside down like a little boat; Hal writes on his slate with his tongue out; Scally leans in shouting and pointing at the boot, delighted; Tabitha holds the apple; Walt stands behind with his arms folded and a small proud smile. Exactly Hal, Scally, Tabitha, Walt.",
 "b12_raft_build": "DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. A busy riverbank, wood chips flying. In the foreground Titch (red cap) kneels hauling a rope tight with both fists, tongue between her teeth, tying a thick knot round a log; Walt swings an axe at a fallen log behind her; Hal and Tabitha stagger carrying a long plank between them; Scally holds the end of a rope upside down, scratching his head in confusion; Hopsi, calm, hammers a plank onto the deck with a stone; Gucci chews a rope end and Dumpling the donkey watches from the bank. Everyone moving in different directions.",
 "b13_raft_spin": "The raft of tied logs spins in the current of the green pool; Hal shouts holding a long pole that doesn't reach; Titch on the bank leans back hauling on a rope tied to a tree; Scally in his socks is tumbling off the side in a perfect flat splash, arms flung up, mouth open; Walt on the bank roars with his pole raised; Hopsi on the raft clutches her hops high. Dramatic and funny. Exactly Hal, Titch, Scally, Hopsi, Walt, Gucci.",
 "b14_rescue_pool": "Titch throws a rope loop; Scally in the water grabs it, spluttering, hair plastered; on the bank Hal, Tabitha, Hopsi and Walt haul together and Gucci hangs onto the rope's end with his teeth; a single brown boot floats away downstream, upright and dignified, like a tiny ship. Everyone hauling in a chain, diagonal rope, straining faces. Exactly Titch, Scally, Hal, Tabitha, Hopsi, Walt, Gucci.",
 "b15_meander": "A wide flat green valley with a stream looping in great lazy bends like a dropped rope. In the foreground Walt sits on a rock drawing a bend in the dust with a stick while the children crouch round him: Hal with his slate, Titch pointing at a bend and laughing, Tabitha tracing the current with a finger, Hopsi listening gravely. Scally sits apart on a log with a sock raised, scratching his head and eyeing a narrow neck of grass between two bends. Exactly Walt, Hal, Titch, Tabitha, Hopsi, Scally.",
 "b16_pebbles": "Close-up of Hal's two hands holding a smooth round grey pebble in one palm and a sharp broken stone in the other, the stream beside him; Hal looks from one to the other with a puzzled frown; Walt, smiling slowly, leans over his shoulder pointing at the round one. Warm light on wet stones. Exactly Hal and Walt.",
 "b17_clay_rescue": "A foggy meadow. Scally stands knee-deep in grey clay in the middle of a neck of ground with his arms out and a green, frightened face; Hopsi lies flat on her stomach with her arms stretched toward him, Titch lies behind her holding her ankles, Hal braces with a rope tied round his waist, Walt shouts instructions with his pole out. Mist swirls. Tense and dramatic but not gory. Exactly Scally, Hopsi, Titch, Hal, Walt.",
 "b18_campfire": "DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. Night on a stony shelf above a stream. Seen from low down: a small fire burns in a ring of pebbles with a full bucket of water beside it. Walt crouches stirring a stew pot; Hal leans in to watch the flames carefully; Gucci rests his chin on Hal's knee staring greedily at Titch's cheese; Titch passes a crust across the fire to Tabitha, who reaches for it. On the far side Scally slips a wrapped bite of cheese inside his jacket with a furtive glance, while across the flames Hopsi watches the cloth with a calm knowing look. Dumpling chews in the dark behind. Warm firelight and stars. Everyone leaning, reaching or eating.",
 "b19_cheese_split": "By the campfire at night: Scally sits hunched with his hands out, ashamed and honest; Titch kneels in front of him and breaks a piece of cheese evenly into two halves on a flat stone, handing one half to him with a kind, no-nonsense look. The fire glows between them. Hopsi watches from the far side with a soft half-smile. Exactly Scally, Titch, Hopsi.",
 "b20_voice_in_water": "DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. Night by a black stream close to the campfire's glow. Thin golden letters and wisps of mist rise from the water in the shape of a tall thin man in a long coat. Gucci stands stiff-legged at the water's edge growling with his hackles up; Hopsi leaps to her feet, white-faced, with her hand over her mouth; Hal grips his slate; Titch clutches Tabitha's arm and ducks behind her; Tabitha leans forward toward the voice, listening hard with one hand cupped to her ear; Scally scrambles back on his hands with eyes wide; Walt sits very still with his old face lit by the fire. Everyone reacting differently.",
 "b21_three_stones": "Dusk on a stony shelf. Hopsi (pointed ears, hops wreath) kneels and sets three white stones in a row across the path, her hand moving the middle one aside and back again, face thoughtful; behind her the other children are rolling out blankets and the campfire glows. Only Hopsi in focus with the rest small in the background.",
 "b22_falls_climb": "DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. A great grey waterfall roaring into a boiling white pool, wet spray. A steep wet path climbs beside it and the children haul themselves up on a rope, some bending forward, some slipping: Scally in front scrambling on all fours in his socks, laughing; Titch behind him gripping the rope with both fists; Hal reaching back to give Tabitha a hand; Hopsi lifting her skirts; at the bottom Walt coaxes the small grey donkey Dumpling up a step by her halter while Gucci scrambles between legs. Strong diagonal up the picture.",
 "b23_echo_trick": "A rocky ledge above the falls with a cliff across the gorge. Scally hides behind a boulder with his hands cupped round his mouth, shouting, a cheeky grin showing round the rock; Titch stands with arms folded and one eyebrow raised; Hopsi walks round the boulder with a small knowing smile, pointing at his socks sticking out; Hal holds up a hand to time the echo; golden echo rings spread across the gorge. Exactly Scally, Titch, Hopsi, Hal.",
 "b24_oak_struck": "A violent storm on an open shoulder of rock. A lightning bolt strikes a huge lone oak at the top and the tree splits, half of it falling across a rock. In the foreground the children and baby Gucci are crouched low in a heather hollow in a tight bundle, hands over ears, Walt sheltering Dumpling's head over his back, Scally in the middle of the heap grey-faced staring back at the falling tree. Rain, wind, violet light. Dramatic. Exactly the six children, Gucci, Walt and Dumpling.",
 "b25_flood_rope": "A roaring brown flood sweeping up a rocky gorge path. Old Walt is waist-deep, swaying, holding the end of a rope; Scally stands at the water's edge with the rope tied round his waist and his arm out, face tense; Hal sits braced on a boulder with the rope round his middle, heels dug in, shouting; Titch leads the small grey donkey Dumpling up the path with the rope looped round her chest; Hopsi and Tabitha stand on the ledge above holding Gucci. Rain, spray, fast water. Tense but not gory.",
 "b26_flood_ledge": "DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. A high rocky ledge above a brown flood foaming through the gorge, sweeping away the lower path, sticks and a small tree. In the foreground, exhausted, Walt lies flat on his back with his stiff leg out, gasping; Scally sits up beside him staring at his own shaking hands; Hal drags the soaked rope out of the water, coiling it; Tabitha pulls a blanket round Walt; Titch hugs Dumpling's neck; Hopsi wraps her arms round Gucci. Everyone slumped and soaked, in a loose tumbled heap, late grey light.",
 "b27_whirlpool": "Dusk at the Source: a huge black round pool as wide as a barn with a great slow glowing golden whirlpool in the middle, and rising from it a faint pale mist shaped like a very tall man in a long coat. The children stand at the edge in a rope chain, small against it: Scally in socks at the front, shivering, Hal and Tabitha holding the rope, Titch holding Gucci, Hopsi standing a little way from the edge with her hand out, Walt with his pole, Dumpling behind. Golden music notes in the mist. Awe and a little fear.",
 "b28_hat_lie": "At the whirlpool edge Scally throws his arms wide and shouts at the mist with his hands cupped, a huge cocky grin on his face; the whirl behind him is beginning to spin faster and the mist leans toward him; Hopsi has her hand on his arm with a worried frown; Hal stands behind with his slate; the tiny brown bird on Scally's head is flapping. Exactly Scally, Hopsi, Hal and the bird, with the whirlpool.",
 "b29_gucci_saved": "At the edge of the whirlpool Titch lies flat on her stomach, one hand clenched in the scruff of baby wolf Gucci who is being dragged toward the whirl, her boots caught in the water. Hal and Scally throw all their weight on the long end of a fallen log lying across a boulder, the short end lifting a rope upward; Tabitha grips Hal's belt, Walt holds Dumpling's halter, the rope taut. Gucci yelps, eyes huge. Dynamic, tense.",
 "b30_slate_data": "Dusk on the bank of the Source. The children sit in a loose ring on the grass, wet and tired, round Hal's soggy slate, on which Hal writes with a tiny stub of chalk; Hopsi sits beside him reading over his shoulder; Titch has Gucci wrapped in her coat; Tabitha holds a canteen to Walt's lips; Dumpling lies with her nose in Hal's pocket looking for an apple; Scally sits apart with his arms round his knees, quiet. Behind them the whirlpool turns dimly. Exactly the six children, Gucci, Walt and Dumpling.",
 "b31_hopsi_i_think": "Hopsi stands alone at the very edge of the bank in a cold wind off the whirlpool, hands clenched at her sides, hair blowing, looking up bravely at the pale tall mist, her mouth open in a clear small voice; the golden whirl is just slowing, its ripples widening; behind her the others watch in silence. Hopsi in the foreground; the rest small and still.",
 "b32_fifth_note": "At the whirlpool the small brown bird Fourpence, perched on Dumpling's ear, sings with its head thrown back, and a single round golden note rises like a drop of light; the whirl has slowed to calm; Scally stands with the wind in his black hair, quiet, speaking; the children stare at the bird, Hopsi with her hands pressed to her mouth, Tabitha smiling, Titch grinning; Walt has tears running into his beard. Warm gold light. Emotional climax.",
 "b33_mist_bows": "DYNAMIC DIAGONAL COMPOSITION, a low or high camera angle, characters at different heights, overlapping, mid-action and reacting to each other, nobody facing the viewer, no row. Dusk. The pale mist above the calm black pool has thinned into long soft rags and for a moment shows a thin, tired, relieved face with a smile no longer too big, bowing once toward Scally. Scally stands at the water's edge with his mouth open, one hand half raised; Hopsi catches his sleeve to hold him back; Hal, Titch and Tabitha stare up from behind with open mouths, Tabitha dropping her apple; Gucci tilts his head. First star above, low silver fog on the water. Quiet and mysterious.",
 "b34_stream_sleeps": "Night at the Source. The black pool is perfectly smooth and the stars lie in it; a thin stream trickles away over stones like a child breathing in its sleep. Walt kneels at the water with tears in his beard, one hand in the stream; Hopsi sits on her stone with her face in her hands, Scally hovering beside her anxiously; Tabitha, Titch, Hal and Gucci lie in a heap in blankets already asleep. Peaceful and tender.",
 "b35_homecoming": "Evening in the mill yard, golden light, the whole village waiting. Hal's mother, a warm weathered woman in a kerchief, lifts Hal clean off the ground in a fierce hug; his father the miller on a stick wipes his eyes; the Mayor takes off his hat and bows his head; Mrs Crumb hands out black-bottomed buns; Walt rides Dumpling in at the gate; the other children and Gucci stand grinning. Warm, joyful. Adults have round ears.",
 "b36_walt_boots": "In the mill yard in the morning Old Walt crouches stiffly and puts a pair of old, big, well-oiled brown boots into Scally's hands; Scally stares at them, speechless, ears red, hands trembling; Hopsi stands behind him smiling; the small grey donkey Dumpling looks on. Exactly Walt, Scally, Hopsi and Dumpling.",
 "b37_sign_facedown": "The mill step in sunshine. Scally, in his big new boots, has just turned a hand-painted board of unreadable black scribbles face-down on the step, a pot of black paint beside him, his brush dripping, looking out at the garden with a sober face; at the gate Hopsi leans on the post with a bowl of hops, one hop in her mouth, watching with a small proud smile. Exactly Scally and Hopsi.",
 "b38_eggs_round": "Long grass behind the mill. Nine cream-coloured eggs in a row are changing shape, their sharp corners wearing smooth and rounding, one rolling in a little circle, one cracking. Scally, Hopsi, Titch and Hal kneel round them in different poses (Hal spinning an egg on the step like a top, Titch staring open-mouthed, Scally with his nose almost touching an egg, Hopsi explaining with a finger raised). Warm morning light. Exactly Scally, Hopsi, Titch, Hal.",
 "b39_gosling_boots": "A big indignant fluffy gosling stands on top of Scally's big brown boot and has firmly attached itself to it by the laces, honking; Scally stands very stiff looking down at it, arms out, disgusted; nine tiny ducklings tumble out of broken eggs behind; Hopsi in the background has a hand over her mouth, shaking with laughter. Funny. Exactly Scally, the gosling, ducklings and Hopsi.",
 "b40_long_way": "A golden autumn lane winding off to a willow tree. Scally walks away down the lane in his big boots with a goose waddling at his heels, not looking back; on the mill step behind, small in the distance, the other children and Gucci watch him go, Hal with an amazed grin, Titch with her hand to her mouth; the sky behind them is beginning to turn grey. Only the lane and Scally big in the foreground.",
 "b41_rain": "Dusk rain beginning over the mill. Hopsi sits on the step with her head tilted back, a bowl of hops in her lap, the first big drops landing on the stone beside her and on her hand, a calm happy smile on her face; Hal beside her holding up his slate to catch a drop; Gucci asleep across everyone's feet; on the roof the little brown bird sings with its head back; the pond below reflects Hal looking relaxed. Cosy.",
}

if __name__ == "__main__":
    names = sys.argv[1:] or list(S)
    for n in names:
        gen.edit_with(n, REF, BASE + EXTRA + S[n], "3:2")
